llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Zidovudine, a small polar neutral nucleoside with high TPSA and low logD, has absolute oral bioavailability of 54–74% in humans, directly supporting that similar physicochemical polarity does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Didanosine, another polar nucleoside, shows absolute oral bioavailability of 42% in patients, supporting high bioavailability for small polar molecules despite transporter and first-pass effects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine has absolute oral bioavailability of 93% in humans, demonstrating that highly polar, low-logD small molecules can achieve excellent oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Thiocolchicoside, a polar glycoside with multiple rings and hydroxyls, has oral bioavailability of 27%, supporting F ≥ 20% for complex polar natural-product-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "BMS-275183, a complex polycyclic taxane analogue containing epoxide-like and ester functionality, has 24% oral bioavailability in humans, supporting F ≥ 20% for rigid polycyclic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Ursodeoxycholic acid, a polar steroid-like molecule with multiple hydroxyls, has 50% systemic availability in healthy subjects, supporting high oral bioavailability for polycyclic polar compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Amphotericin B has negligible oral bioavailability, but this is attributed to its very large polyene macrolide size, poor solubility, and acid instability—features not shared by the much smaller, more soluble query molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: multiple high-transfer analogues with diverse polar and polycyclic scaffolds show absolute oral bioavailability ≥20%, including zidovudine (54–74%), emtricitabine (93%), didanosine (~42%), thiocolchicoside (27%), BMS-275183 (24%), and UDCA (50%). The query's small size, favorable solubility, and neutral polar profile align with these compounds. The only low-bioavailability analogue, amphotericin B, is an extreme outlier mechanistically and does not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "Unknown whether the query is a substrate for intestinal transporters or efflux pumps.",
    "First-pass metabolism and chemical stability in the gastrointestinal tract are not directly assessed.",
    "Amphotericin B low-F evidence raises a permeability concern, but its mechanism is not clearly transferable to this smaller, more soluble scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

